import React, { CSSProperties, forwardRef } from 'react';
import { isElement } from 'react-is';

import Spacings from '@dynatrace/strato-design-tokens/spacings';

import { SharedProgressBarPropsContext } from './contexts/SharedProgressBarPropsContext.js';
import { _useProgressAriaProps } from './hooks/useProgressAriaProps.js';
import { progressBarFillCSS, progressCSS } from './ProgressBar.sty.js';
import { ProgressBarIcon } from './ProgressBarIcon.js';
import { ProgressBarLabel } from './ProgressBarLabel.js';
import { ProgressBarValue } from './ProgressBarValue.js';
import { _useAriaLabelingProps } from '../../hooks/useAriaLabelingProps.js';
import { _useId } from '../../hooks/useId.js';
import { _useSafeForwardProps } from '../../hooks/useSafeForwardProps.js';
import type { AriaLabelingProps } from '../../types/a11y-props.js';
import type { DataTestId } from '../../types/data-props.js';
import type { DOMProps } from '../../types/dom.js';
import type { RoleVariantType } from '../../types/role-variant.js';
import type { StylingProps } from '../../types/styling-props.js';
import type { WithChildren } from '../../types/with-children.js';

export type ProgressBarDensity = 'default' | 'condensed';

/** Accepted properties for ProgressBar */
export interface ProgressBarProps
  extends WithChildren,
    DOMProps,
    AriaLabelingProps,
    StylingProps,
    DataTestId {
  /**
   * The current value.
   * @defaultValue 'indeterminate'
   */
  value?: number | 'indeterminate';
  /**
   * The minimum allowed value.
   * @defaultValue 0
   */
  min?: number;
  /**
   * The maximum allowed value.
   * @defaultValue 100
   */
  max?: number;
  /**
   * Controls the density of the rendering.
   * @defaultValue 'default'
   */
  density?: ProgressBarDensity;
  /**
   * Controls the appearance of the progress.
   * @defaultValue 'primary'
   */
  variant?: RoleVariantType;
  /**
   * The aria-valuetext attribute defines the human-readable text alternative of aria-valuenow for a range widget.
   * By default, the value will be given as a percentage. If the value is not a percentage, you should provide aria-valuetext.
   * https://developer.mozilla.org/en-US/docs/Web/Accessibility/ARIA/Attributes/aria-valuetext
   * @defaultValue the value of the progress as percentage.
   */
  'aria-valuetext'?: string;
}

type ProgressBarSlots = {
  value?: React.ReactNode;
  label?: React.ReactNode;
  icon?: React.ReactNode;
};

function getProgressBarSlots(children: React.ReactNode) {
  const slots: ProgressBarSlots = {
    value: null,
    label: null,
    icon: null,
  };

  React.Children.forEach(children, (child) => {
    if (isElement(child)) {
      switch (child.type) {
        case ProgressBarLabel:
          slots.label = child;
          break;
        case ProgressBarIcon:
          slots.icon = child;
          break;
        case ProgressBarValue:
        default:
          slots.value = child;
          break;
      }
    } else {
      if (!slots.value) {
        slots.value = child;
      }
    }
  });

  return slots;
}

const _ProgressBar = forwardRef<HTMLDivElement, ProgressBarProps>(
  (props, forwardedRef) => {
    const {
      value: originalValue,
      max = 100,
      min = 0,
      density = 'default',
      variant = 'primary',
      children,
      id: propId,
      'aria-valuetext': ariaValuetext,
      className: consumerClassName,
      style: consumerStyle,
      'data-testid': dataTestId,
      ...remainingProps
    }: ProgressBarProps = props;

    const slots = getProgressBarSlots(children);
    const { value, isIndeterminate, progressAriaProps } = _useProgressAriaProps(
      originalValue,
      min,
      max,
      ariaValuetext,
    );
    const ariaLabelingProps = _useAriaLabelingProps(remainingProps);
    const forwardProps = _useSafeForwardProps(
      remainingProps,
      ariaLabelingProps,
    );

    const generatedId = _useId({ prefix: 'progress-bar' });
    const id = propId ?? generatedId;

    if (
      !slots.label &&
      !ariaLabelingProps['aria-label'] &&
      !ariaLabelingProps['aria-labelledby']
    ) {
      process.env.NODE_ENV === 'development' &&
        // eslint-disable-next-line no-console
        console.warn(
          'If no label is provided please make sure to provide an aria label on your progressCircle element.',
        );
    }

    const progressStyles: CSSProperties = {};
    if (!isIndeterminate && value !== undefined) {
      const percentage = (value - min) / (max - min);
      progressStyles['width'] = `${Math.round(percentage * 100)}%`;
    }

    return (
      <SharedProgressBarPropsContext.Provider value={{ id, variant, density }}>
        {/* TODO: this can be replaced by using the FLEX component. Using the flex component currently causes a circular from core -> layout -> core */}
        <div
          className={consumerClassName}
          style={{
            display: 'flex',
            flexDirection: 'column',
            gap: Spacings.Size6,
            width: '100%',
            ...consumerStyle,
          }}
          data-testid={dataTestId}
          ref={forwardedRef}
          {...forwardProps}
        >
          {/* //TODO: this can be replaced by using the FLEX component. Using the flex component currently causes a circular from core -> layout -> core */}
          <div
            style={{
              display: 'flex',
              justifyContent: 'space-between',
              gap: Spacings.Size8,
            }}
          >
            {density === 'condensed' ? (
              <div
                style={{
                  display: 'flex',
                  justifyContent: 'space-between',
                  alignItems: 'flex-end',
                  flex: 1,
                  gap: Spacings.Size16,
                  minWidth: 0,
                }}
              >
                {/* //TODO: this can be replaced by using the FLEX component. Using the flex component currently causes a circular from core -> layout -> core */}
                {slots.label}
                {density === 'condensed' && slots.value}
              </div>
            ) : (
              slots.label
            )}
            {slots.icon}
          </div>
          <div
            className={progressCSS({ size: density, variant })}
            id={id}
            {...progressAriaProps}
            {...ariaLabelingProps}
          >
            <div
              className={progressBarFillCSS({
                variant,
                indeterminate: isIndeterminate,
              })}
              style={progressStyles}
            />
          </div>
          {density === 'default' && slots.value}
        </div>
      </SharedProgressBarPropsContext.Provider>
    );
  },
);

(_ProgressBar as typeof _ProgressBar & { displayName: string }).displayName =
  'ProgressBar';

/**
 * Use the `ProgressBar` component to show your users that a system operation such as downloading, uploading, or processing is progressing.
 * The `ProgressBar` can be used to visualize determinate or indeterminate progress.
 */
export const ProgressBar = Object.assign(_ProgressBar, {
  Value: ProgressBarValue,
  Label: ProgressBarLabel,
  Icon: ProgressBarIcon,
});
